import {isDate,dateKey} from './calendar-27ca4e179461.mjs';
export function renderMonthPicker({body,footer,node,value,onPick,close,min='',max='',today=dateKey()}){
 const initial=/^\d{4}-\d{2}$/.test(value)?value:today.slice(0,7),box=node('section','date-picker'),fields=node('div','date-picker-fields'),error=node('p','form-error');body.append(box);box.append(fields,error);error.hidden=true;error.setAttribute('role','alert');const inputs=[];
 for(const [name,val,lo,hi]of [['年份',initial.slice(0,4),1,9999],['月份',initial.slice(5),1,12]]){const label=node('label','',name),input=node('input');input.type='number';input.inputMode='numeric';input.min=lo;input.max=hi;input.value=String(Number(val));input.setAttribute('aria-label','选择'+name);label.append(input);fields.append(label);inputs.push(input);}
 const cancel=node('button','secondary','取消'),done=node('button','primary','确定月份');cancel.type=done.type='button';cancel.onclick=close;done.onclick=()=>{const month=String(Number(inputs[0].value)).padStart(4,'0')+'-'+String(Number(inputs[1].value)).padStart(2,'0');if(!isDate(month+'-01')||(min&&month<min)||(max&&month>max)){error.textContent='请选择有效范围内的年份和月份';error.hidden=false;return;}onPick(month);};footer.append(cancel,done);
}
export function renderDatePicker({body,footer,node,value,onPick,close,min='',max='',today=dateKey()}){
 const initial=isDate(value)?value:today,box=node('section','date-picker'),head=node('div','date-picker-heading'),prev=node('button','text-button','‹'),next=node('button','text-button','›'),caption=node('button','text-button'),fields=node('div','date-picker-fields'),grid=node('div','date-picker-grid'),error=node('p','form-error');
 prev.type=next.type=caption.type='button';prev.setAttribute('aria-label','上个月');next.setAttribute('aria-label','下个月');head.append(prev,caption,next);box.append(head,fields,grid,error);body.append(box);error.hidden=true;error.setAttribute('role','alert');let month=initial.slice(0,7);
 const inputs={};for(const [key,name,v,lo,hi]of [['year','年',initial.slice(0,4),1,9999],['month','月',initial.slice(5,7),1,12],['day','日',initial.slice(8,10),1,31]]){const label=node('label','',name),input=node('input');input.type='number';input.inputMode='numeric';input.min=lo;input.max=hi;input.value=String(Number(v));input.setAttribute('aria-label',key==='year'?'选择年份':key==='month'?'选择月份':'选择日期中的日');label.append(input);fields.append(label);inputs[key]=input;}
 const pick=date=>{if(!isDate(date)||(min&&date<min)||(max&&date>max)){error.textContent='请选择有效日期'+(min||max?'，范围为'+(min||'不限')+'至'+(max||'不限'):'');error.hidden=false;return;}onPick(date);};
 function draw(){caption.textContent=month.slice(0,4)+'年'+Number(month.slice(5))+'月';caption.setAttribute('aria-label','输入年份与月份，当前'+caption.textContent);grid.replaceChildren();for(const day of ['一','二','三','四','五','六','日'])grid.append(node('span','date-weekday',day));const start=month+'-01',offset=(new Date(start+'T12:00:00Z').getUTCDay()+6)%7;for(let i=0;i<offset;i++)grid.append(node('span'));
  for(let day=1;day<=31;day++){const date=month+'-'+String(day).padStart(2,'0');if(!isDate(date))break;const b=node('button','date-day',String(day));b.type='button';b.setAttribute('aria-label',date);b.setAttribute('aria-pressed',String(date===value));b.dataset.date=date;b.disabled=!!(min&&date<min||max&&date>max);if(date===today)b.setAttribute('aria-current','date');b.onclick=()=>pick(date);grid.append(b);}
 }
 const shift=delta=>{const [year,mo]=month.split('-').map(Number),n=year*12+mo-1+delta,y=Math.floor(n/12),m=n%12+1;if(y<1||y>9999)return;month=String(y).padStart(4,'0')+'-'+String(m).padStart(2,'0');inputs.year.value=String(y);inputs.month.value=String(m);draw();};prev.onclick=()=>shift(-1);next.onclick=()=>shift(1);caption.onclick=()=>{inputs.year.focus();inputs.year.select();};
 const typed=()=>String(Number(inputs.year.value)).padStart(4,'0')+'-'+String(Number(inputs.month.value)).padStart(2,'0')+'-'+String(Number(inputs.day.value)).padStart(2,'0');for(const key of ['year','month'])inputs[key].onchange=()=>{const candidate=typed().slice(0,7);if(isDate(candidate+'-01')){month=candidate;draw();}};
 const cancel=node('button','secondary','取消'),confirm=node('button','primary','确定日期');cancel.type=confirm.type='button';cancel.onclick=close;confirm.onclick=()=>pick(typed());footer.append(cancel,confirm);draw();
 const resize=new ResizeObserver(()=>{const narrow=box.clientWidth<308;box.dataset.compact=String(narrow);grid.hidden=narrow;});resize.observe(box);return ()=>resize.disconnect();
}
